import styled from 'styled-components';

export const SectionTitle = styled.h2`
  font-size: 2rem;
  font-weight: 500;
  color: var(--primary-text);
  padding-top: 4rem;
  margin-bottom: 2rem;
`;

export const GridContainer = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 2rem;
  padding-bottom: 4rem;
`;
